!function(){"use strict";app.factory("liquidacionCompraService",(function($injector){const url="/LiquidacionCompra/";let mS=$injector.get("mainService");return{getAll:getAll};function getAll(query){return mS.getData("get",url+"Get?json="+JSON.stringify(query)).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let results;return(JSON.parse(response.payload)||[]).map(item=>({codEstab:item.codEstab,idLiquidacionCompra:item.idLiquidacionCompra,fechaEmision:item.fechaEmision,total:item.total,nroDocumento:item.nroDocumento,nombreFiscal:item.nombreFiscal,estadoFinanciero:item.estadoFinanciero,style:item.style,usuario:item.usuario,codDoc:item.codDoc,codEstado:item.codDoc}))}})}}))}(window.angular);